<tr class="add-row" data-add-row>
    <td><i class="ri-add-line text-muted"></i></td><td>جدید</td>
    <td><input form="add-item-form" name="field_code" class="form-control selection-input" data-catalog-input data-field="field_code" placeholder="کد رشته" required></td>
    <td><input form="add-item-form" name="field_name" class="form-control selection-input" data-catalog-input data-field="field_name" placeholder="نام رشته" required></td>
    <td><textarea form="add-item-form" name="field_description" class="form-control selection-input selection-textarea" data-field="field_description" rows="1" placeholder="توضیحات رشته"></textarea></td>
    <td><input form="add-item-form" name="university_name" class="form-control selection-input" data-field="university_name" placeholder="نام دانشگاه"></td>
    <td><input form="add-item-form" name="city" class="form-control selection-input" data-field="city" placeholder="شهر" required></td>
    <td><input form="add-item-form" name="university_type" class="form-control selection-input" data-field="university_type" placeholder="نوع دانشگاه"></td>
    <td><button class="btn btn-sm btn-primary" type="submit" form="add-item-form" title="افزودن"><i class="ri-add-line"></i> افزودن</button></td>
</tr>
